      "id": "reactor-27816",
      "title": "Deployment Stacks: Azure's Standard for Infrastructure as Code, Drift Detection, and",
      "start": "2027-01-27T18:00:00.000Z",
      "end": "2027-01-28T03:00:00.000Z",
      "format": "Online",
